export type ContentKind = "tourist-place" | "accommodation" | "restaurant" | "entertainment" | "event" | "emergency" | "user";
export type ContentField = "name" | "description" | "shortDescription" | "category" | "location" | "address" | "hours" | "services" | "highlights" | "status" | "type" | "institution" | "role" | "language" | "nationality" | "periodicity" | "month" | "price" | "registeredBy";

export type EnglishRecordTranslations = Partial<Record<ContentField, string | Record<string, string>>>;
const dynamicTranslationsKey = "turismosucre_record_translations_en_v1";
const readDynamicTranslations = (): Record<string, EnglishRecordTranslations> => {
  try {
    return typeof localStorage === "undefined" ? {} : JSON.parse(localStorage.getItem(dynamicTranslationsKey) ?? "{}") as Record<string, EnglishRecordTranslations>;
  } catch { return {}; }
};

export function getRecordEnglishTranslations(kind: ContentKind, id: string): EnglishRecordTranslations {
  return readDynamicTranslations()[`${kind}:${id}`] ?? {};
}

export function getRecordEnglishField(kind: ContentKind, id: string, field: ContentField): string {
  const dynamic = getRecordEnglishTranslations(kind, id)[field];
  if (typeof dynamic === "string" && dynamic.trim()) return dynamic;
  return field === "name" ? recordEnglishNames[`${kind}:${id}`] ?? recordEnglish[`${kind}:${id}`]?.name ?? "" : recordEnglish[`${kind}:${id}`]?.[field] ?? "";
}

export function saveRecordEnglishTranslations(kind: ContentKind, id: string, translations: EnglishRecordTranslations): void {
  try {
    if (typeof localStorage === "undefined") return;
    const current = readDynamicTranslations();
    localStorage.setItem(dynamicTranslationsKey, JSON.stringify({ ...current, [`${kind}:${id}`]: { ...translations, name: translations.name ?? "" } }));
  } catch (error) {
    console.error("No se pudieron guardar las traducciones del registro.", error);
  }
}

export function translateText(value: string | undefined, language: Language): string {
  if (!value || language === "es") return value ?? "";
  if (commonEnglish[value]) return commonEnglish[value];
  const countMatch = value.match(/^(\d+) (registros|eventos|lugares) encontrados$/i);
  if (countMatch) {
    const noun = countMatch[2].toLowerCase() === "eventos" ? "events" : countMatch[2].toLowerCase() === "lugares" ? "places" : "records";
    return `${countMatch[1]} ${noun} found`;
  }
  return value
    .replace(/\b(ACTIVO|INACTIVO)\b/g, (word) => commonEnglish[word])
    .replace(/\b(RECURRENTE|PROXIMO|EN_CURSO|FINALIZADO|CANCELADO)\b/g, (word) => commonEnglish[word] ?? word);
}

export function translateRecordText(kind: ContentKind, id: string, field: ContentField, value: string | undefined, language: Language): string {
  if (!value || language === "es") return value ?? "";
  const dynamicRecord = getRecordEnglishTranslations(kind, id);
  const dynamicField = dynamicRecord[field];
  if (typeof dynamicField === "string" && dynamicField.trim()) return dynamicField;
  if (dynamicField && typeof dynamicField === "object" && dynamicField[value]?.trim()) return dynamicField[value];
  if (Object.keys(dynamicRecord).length > 0 && ["name", "description", "shortDescription", "category", "location", "address", "hours", "services", "highlights", "type", "institution", "periodicity"].includes(field)) {
    return "English translation pending";
  }
  const recordValue = recordEnglish[`${kind}:${id}`]?.[field];
  if (recordValue) return recordValue;
  if (field === "name" && recordEnglishNames[`${kind}:${id}`]) return recordEnglishNames[`${kind}:${id}`];
  const common = translateText(value, language);
  if (common !== value) return common;
  if (field === "month") {
    const months: Record<string, string> = { enero: "January", febrero: "February", marzo: "March", abril: "April", mayo: "May", junio: "June", julio: "July", agosto: "August", septiembre: "September", octubre: "October", noviembre: "November", diciembre: "December" };
    return value.replace(/\b(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)\b/gi, (month) => months[month.toLowerCase()]);
  }
  const replacements: Array<[RegExp, string]> = [
    [/\bCalle\b/gi, "Street"], [/\bAvenida\b/gi, "Avenue"], [/\bAv\./gi, "Ave."], [/\bPasaje\b/gi, "Passage"],
    [/\besquina\b/gi, "corner of"], [/\bfrente al\b/gi, "opposite the"], [/\bfrente a la\b/gi, "opposite the"], [/\bfrente a\b/gi, "opposite"], [/\bbarrio\b/gi, "neighborhood"], [/\bzona\b/gi, "area"], [/\bN[.º°]+\b/g, "No."], [/\b24 horas\b/gi, "24 hours"],
    [/\bentre\b/gi, "between"], [/\by\b/gi, "and"], [/\bPlazuela\b/gi, "Small Square"], [/\bPlaza\b/g, "Square"], [/\bcarretera\b/gi, "Highway"],
    [/\bCentro histórico\b/gi, "Historic center"], [/\bcentro de Sucre\b/gi, "downtown Sucre"], [/\bciudad de Sucre\b/gi, "City of Sucre"],
    [/Carga inicial verificada con fuentes institucionales/gi, "Initial entry verified against institutional sources"], [/Vías y espacios públicos de Sucre, Bolivia; actividades municipales distribuidas por puntos de la ciudad/gi, "Public roads and spaces across Sucre, Bolivia; municipal activities are held at locations throughout the city"], [/dirección física no especificada/gi, "physical address not specified"], [/dirección postal no publicada en el directorio municipal/gi, "postal address not listed in the municipal directory"],
    [/dirección no publicada en el directorio municipal/gi, "address not listed in the municipal directory"], [/línea de atención/gi, "service line"],
    [/Lun\. a vie\./g, "Mon. to Fri."], [/Lun\. a sáb\./g, "Mon. to Sat."], [/Sáb\. y dom\./g, "Sat. and Sun."], [/Sáb\./g, "Sat."], [/dom\./g, "Sun."],
    [/lunes a viernes/gi, "Monday to Friday"], [/lunes a sábado/gi, "Monday to Saturday"], [/sábado/gi, "Saturday"], [/domingo/gi, "Sunday"],
    [/atención permanente/gi, "continuous service"], [/consulta externa/gi, "outpatient care"], [/según publicación municipal de 2018/gi, "according to a 2018 municipal notice"],
    [/pendiente de reconfirmación actual/gi, "pending current reconfirmation"], [/horario y programación publicados en el anuncio municipal/gi, "hours and program published in the municipal announcement"],
    [/anual; fecha y recorrido sujetos a organización de la FUL y autorización municipal de cada gestión/gi, "Annual; date and route depend on FUL organization and municipal authorization each year"],
    [/dos jornadas al año: cuarto domingo de junio y primer domingo de septiembre, de acuerdo con la Ley Municipal 500\/2026; sujeto a convocatoria o ajuste anual/gi, "Two days each year: the fourth Sunday in June and the first Sunday in September, under Municipal Law 500/2026; subject to the annual announcement or changes"],
    [/tres domingos al mes en la plaza y un cuarto domingo con área ampliada, según Ley Municipal 518\/2026/gi, "Three Sundays a month in the square and a fourth Sunday with an expanded area, under Municipal Law 518/2026"],
  ];
  const translated = replacements.reduce((result, [pattern, replacement]) => result.replace(pattern, replacement), value);
  const containsSpanish = /\b(?:el|la|los|las|de|del|en|para|con|y|calle|avenida|plaza|lunes|martes|miércoles|jueves|viernes|sábado|domingo|atención|servicio|ubicado|ubicada|restaurante|hospedaje|museo|iglesia|parque|horario|entrada|salida|frente|entre|barrio|zona)\b/i.test(translated);
  return translated === value && containsSpanish ? "English translation pending" : translated;
}
